content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background-color: #f0f2f5;
}

.calculator-container {
  width: 100%;
  max-width: 360px;
  background-color: #1a1a1a;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
  overflow: hidden;
  padding: 20px;
}

.display {
  background-color: #262626;
  color: #ffffff;
  font-size: 2.5rem;
  font-weight: 300;
  text-align: right;
  padding: 20px 16px;
  border-radius: 8px;
  margin-bottom: 20px;
  word-break: break-all;
  word-wrap: break-word;
  min-height: 80px;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.btn {
  background-color: #333333;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-size: 1.25rem;
  font-weight: 500;
  padding: 16px 0;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  user-select: none;
  touch-action: manipulation;
}

.btn:hover {
  background-color: #444444;
}

.btn:active {
  transform: scale(0.95);
}

.btn-number {
  background-color: #333333;
}

.btn-number:hover {
  background-color: #444444;
}

.btn-operator {
  background-color: #ff9f0a;
  color: #ffffff;
}

.btn-operator:hover {
  background-color: #ffb03a;
}

.btn-clear {
  background-color: #a5a5a5;
  color: #000000;
}

.btn-clear:hover {
  background-color: #b8b8b8;
}

.btn-equals {
  background-color: #ff9f0a;
  color: #ffffff;
}

.btn-equals:hover {
  background-color: #ffb03a;
}

import { useState } from 'react'

export default function App() {
  const [displayValue, setDisplayValue] = useState<string>('0')
  const [firstOperand, setFirstOperand] = useState<number | null>(null)
  const [operator, setOperator] = useState<string | null>(null)
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false)

  const inputDigit = (digit: string) => {
    if (waitingForOperand) {
      setDisplayValue(digit)
      setWaitingForOperand(false)
    } else {
      setDisplayValue(displayValue === '0' ? digit : displayValue + digit)
    }
  }

  const inputDot = () => {
    if (waitingForOperand) {
      setDisplayValue('0.')
      setWaitingForOperand(false)
      return
    }
    if (!displayValue.includes('.')) {
      setDisplayValue(displayValue + '.')
    }
  }

  const clearAll = () => {
    setDisplayValue('0')
    setFirstOperand(null)
    setOperator(null)
    setWaitingForOperand(false)
  }

  const performCalculation = (nextOperator: string | null) => {
    const inputValue = parseFloat(displayValue)

    if (firstOperand === null) {
      setFirstOperand(inputValue)
    } else if (operator) {
      const currentValue = firstOperand
      let result = currentValue

      switch (operator) {
        case '+':
          result = currentValue + inputValue
          break
        case '-':
          result = currentValue - inputValue
          break
        case '*':
          result = currentValue * inputValue
          break
        case '/':
          result = inputValue === 0 ? 0 : currentValue / inputValue
          break
        default:
          break
      }

      setFirstOperand(result)
      setDisplayValue(String(result))
    }

    setWaitingForOperand(true)
    setOperator(nextOperator)
  }

  return (
    <div className="calculator-container">
      <div className="display">{displayValue}</div>
      <div className="keypad">
        <button className="btn btn-clear" onClick={clearAll}>AC</button>
        <button className="btn btn-operator" onClick={() => performCalculation('/')}>÷</button>
        <button className="btn btn-operator" onClick={() => performCalculation('*')}>×</button>
        <button className="btn btn-operator" onClick={() => performCalculation('-')}>-</button>

        <button className="btn btn-number" onClick={() => inputDigit('7')}>7</button>
        <button className="btn btn-number" onClick={() => inputDigit('8')}>8</button>
        <button className="btn btn-number" onClick={() => inputDigit('9')}>9</button>
        <button className="btn btn-operator" onClick={() => performCalculation('+')}>+</button>

        <button className="btn btn-number" onClick={() => inputDigit('4')}>4</button>
        <button className="btn btn-number" onClick={() => inputDigit('5')}>5</button>
        <button className="btn btn-number" onClick={() => inputDigit('6')}>6</button>
        <button className="btn btn-equals" onClick={() => performCalculation(null)}>=</button>

        <button className="btn btn-number" onClick={() => inputDigit('1')}>1</button>
        <button className="btn btn-number" onClick={() => inputDigit('2')}>2</button>
        <button className="btn btn-number" onClick={() => inputDigit('3')}>3</button>
        <button className="btn btn-number" onClick={() => inputDigit('0')}>0</button>
      </div>
    </div>
  )
}
